describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    googleOAuthBasicAuth: 'base64encodedcredentials',
    googleRefreshToken: 'example-refresh-token',
    googleSpreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
    googleSheetRange: 'Sheet1!A1',
  };

  it('happy path: refreshes token and appends deal stage to sheets', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://oauth2.googleapis.com/token') {
        expect(req.method).toBe('POST');
        expect(req.headers.get('authorization')).toBe('Basic base64encodedcredentials');
        expect(req.body).toBe('grant_type=refresh_token&refresh_token=example-refresh-token');
        return jsonResponse({
          access_token: 'ya29.new-access-token',
          expires_in: 3599,
          token_type: 'Bearer',
        });
      }
      if (req.url.includes('/values/Sheet1!A1:append')) {
        expect(req.method).toBe('POST');
        expect(req.headers.get('authorization')).toBe('Bearer ya29.new-access-token');
        expect(req.json).toEqual({
          majorDimension: 'ROWS',
          range: 'Sheet1!A1',
          values: [['closedwon']],
        });
        return jsonResponse({
          spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
          tableRange: 'Sheet1!A1:A1',
          updates: {
            spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
            updatedRange: 'Sheet1!A1:A1',
            updatedRows: 1,
            updatedColumns: 1,
            updatedCells: 1,
          },
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: HubSpotDealUpdatedPayload = {
      dealId: '12345',
      dealstage: 'closedwon',
    };

    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result).toEqual({
      spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
      updatedRange: 'Sheet1!A1:A1',
      updatedRows: 1,
    });
    expect(calls.length).toBe(2);
  });

  it('uses valueInputOption from config as query parameter', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://oauth2.googleapis.com/token') {
        return jsonResponse({ access_token: 'token', expires_in: 3600, token_type: 'Bearer' });
      }
      if (req.url.includes('valueInputOption=RAW')) {
