          tableRange: 'Sheet1!A1:A1',
          updates: { updatedRange: 'Sheet1!A1:A1', updatedRows: 1, updatedColumns: 1, updatedCells: 1 },
        });
      }
      return jsonResponse({ error: 'bad' }, 400);
    });

    const payload: HubSpotDealUpdatedPayload = { dealId: '1', dealstage: 'stage' };
    await handle(payload, { ...baseConfig, valueInputOption: 'RAW', fetch });
    const sheetsCall = calls.find(c => c.url.includes('/values/'));
    expect(sheetsCall?.url).toContain('valueInputOption=RAW');
  });

