    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { dealstage: 'closedwon' } as HubSpotDealUpdatedPayload;
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: dealId');
  });

  it('throws when deal stage is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { dealId: '123' } as HubSpotDealUpdatedPayload;
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: deal stage');
  });

