    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://oauth2.googleapis.com/token') {
        return jsonResponse({ error: 'invalid_grant' }, 400);
      }
      return jsonResponse({}, 200);
    });

    const payload: HubSpotDealUpdatedPayload = { dealId: '1', dealstage: 'stage' };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Token refresh failed: 400 Bad Request');
    expect(calls.length).toBe(1);
  });

  it('throws on sheets append non-2xx', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://oauth2.googleapis.com/token') {
        return jsonResponse({ access_token: 'token', expires_in: 3600, token_type: 'Bearer' });
      }
      if (req.url.includes('/values/')) {
        return jsonResponse({ error: 'not found' }, 404);
      }
      return jsonResponse({}, 200);
    });

    const payload: HubSpotDealUpdatedPayload = { dealId: '1', dealstage: 'stage' };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Sheets append failed: 404 Not Found');
    expect(calls.length).toBe(2);
